// The stub constructors return implementations that panic on any call — they are
// replaced wholesale in T4.
//
// Compile-time interface assertions live here so they travel with the implementations:
//
//	var _ Writer = (*writerService)(nil)
//	var _ Reader = (*readerService)(nil)
